#!/usr/bin/env python3
"""Generate the Spec 242 four-layer INT4/GQA fixture.

The graph is small but real: every layer runs attention (Q/K/V projections, QK^T,
softmax, AV, O projection) and an MLP, with INT4 packed weights in the layout the
adapter's slice planner expects (`[N, K/32, blob]` nibbles per `packedInt4Bytes`).
Node names follow the classifier contract:

* `model.layers.<n>.` prefixes decide the layer;
* everything before `post_attention_layernorm` in a layer is ATTN, from it onward MLP;
* `layers.<n>` with n == layer count is the final norm (HEAD);
* `lm_head` is HEAD; every other non-layer node is INIT.

The output is deterministic: weights come from a fixed seed, so the same file can be
regenerated byte-identically and its digest is a stable fixture identity.
"""
import argparse
import hashlib
import onnx
from onnx import helper, TensorProto, numpy_helper
import numpy as np

BLOCK = 32
BLOB = 16  # 32 nibbles per block packed into 16 bytes


def packed_int4(rng, n, k):
    """[n, k/32, 16] uint8 nibbles, the layout the adapter slices."""
    assert k % BLOCK == 0
    return rng.integers(0, 256, size=(n, k // BLOCK, BLOB), dtype=np.uint8)


def scales(n, k):
    # Flattened `[N * K/32]`, which is the layout the adapter's slicer narrows: it rewrites
    # `dims(0)` to `rows * blocks` and leaves the tensor one-dimensional.
    return np.full(n * (k // BLOCK), 0.02, dtype=np.float32)


def matmul_nbits(name, x, n, k, rng, base_name):
    # The export names the packed tensor `<base>_Q4` and its scales `<base>_scales`; the
    # adapter's slicer derives both from the slice's logical base name.
    weight_name = base_name + "_Q4"
    scale_name = base_name + "_scales"
    w = numpy_helper.from_array(packed_int4(rng, n, k), weight_name)
    s = numpy_helper.from_array(scales(n, k), scale_name)
    node = helper.make_node("MatMulNBits", [x, weight_name, scale_name],
                            [name], name=name, domain="com.microsoft", block_size=BLOCK,
                            K=k, N=n, bits=4)
    return node, [w, s]


def build(path, layers=4, hidden=64, q_heads=4, kv_heads=2, head_dim=16, ffn=128,
          vocab=64, seed=242, sequence=3, attention='gqa'):
    rng = np.random.default_rng(seed)
    nodes, inits = [], []
    init_names = set()

    def add(node, new_inits=()):
        nodes.append(node)
        for item in new_inits:
            if item.name not in init_names:
                inits.append(item)
                init_names.add(item.name)

    # INIT: token embedding gather and the three side inputs.
    add(helper.make_node("Gather", ["model.embed_tokens.weight", "input_ids"], ["embed"],
                         name="INIT/embed"),
        [numpy_helper.from_array(rng.standard_normal((vocab, hidden)).astype(np.float32),
                                 "model.embed_tokens.weight")])
    add(helper.make_node("Cast", ["embed"], ["x0"], name="INIT/cast", to=TensorProto.FLOAT))

    if attention == 'matmul':
        # No GQA grouping in the numeric fixture: every head owns its own K/V, so a head range
        # is exactly a row range of q, k, v and the shards decompose without a mapping rule.
        kv_heads = q_heads
    q_width, kv_width = q_heads * head_dim, kv_heads * head_dim
    for layer in range(layers):
        p = f"model.layers.{layer}."      # initializer names keep dots
        pn = f"model.layers.{layer}/"     # node names separate the index with a slash
        x = "x0" if layer == 0 else f"model.layers.{layer}/input"
        # Attention block.
        node, w = matmul_nbits(f"{pn}attn.q_proj", x, q_width, hidden, rng,
                               f"{p}attn.q_proj.MatMul.weight")
        add(node, w)
        node, w = matmul_nbits(f"{pn}attn.k_proj", x, kv_width, hidden, rng,
                               f"{p}attn.k_proj.MatMul.weight")
        add(node, w)
        node, w = matmul_nbits(f"{pn}attn.v_proj", x, kv_width, hidden, rng,
                               f"{p}attn.v_proj.MatMul.weight")
        add(node, w)
        for tensor in (
                numpy_helper.from_array(np.zeros((1, kv_heads, 0, head_dim), dtype=np.float32),
                                        f"{pn}attn.past_key"),
                numpy_helper.from_array(np.zeros((1, kv_heads, 0, head_dim), dtype=np.float32),
                                        f"{pn}attn.past_value"),
                numpy_helper.from_array(np.array([0], dtype=np.int32), f"{pn}attn.seqlens_k"),
                numpy_helper.from_array(np.array([sequence], dtype=np.int32),
                                        f"{pn}attn.total_sequence_length")):
            if tensor.name not in init_names:
                inits.append(tensor)
                init_names.add(tensor.name)
        # The maintained export uses the contrib attention op, and the adapter reads the head
        # counts from its attributes; a hand-rolled softmax attention has no such attributes.
        # Real (if empty) state tensors: ONNX Runtime's loader rejects empty strings for
        # these inputs even though the checker and the adapter accept them.
        if attention == 'matmul':
            # Numeric fixture: plain per-head attention. No contrib op, so a head range is a
            # plain weight slice and the whole model decomposes exactly.
            for name, heads, width in (("q", q_heads, q_width), ("k", kv_heads, kv_width),
                                       ("v", kv_heads, kv_width)):
                shape_name = f"{pn}attn.{name}_shape"
                if shape_name not in init_names:
                    inits.append(numpy_helper.from_array(
                        np.array([1, heads, sequence, head_dim], dtype=np.int64), shape_name))
                    init_names.add(shape_name)
                add(helper.make_node("Reshape", [f"{pn}attn.{name}_proj", shape_name],
                                     [f"{pn}attn.{name}4d"], name=f"{pn}attn.{name}_reshape"))
            add(helper.make_node("Transpose", [f"{pn}attn.k4d"], [f"{pn}attn.kT"],
                                 name=f"{pn}attn.kT", perm=[0, 1, 3, 2]))
            add(helper.make_node("MatMul", [f"{pn}attn.q4d", f"{pn}attn.kT"],
                                 [f"{pn}attn.scores"], name=f"{pn}attn.scores"))
            add(helper.make_node("Mul", [f"{pn}attn.scores", "attn.scale"],
                                 [f"{pn}attn.scaled"], name=f"{pn}attn.scale"))
            add(helper.make_node("Softmax", [f"{pn}attn.scaled"], [f"{pn}attn.weights"],
                                 name=f"{pn}attn.softmax", axis=-1))
            add(helper.make_node("MatMul", [f"{pn}attn.weights", f"{pn}attn.v4d"],
                                 [f"{pn}attn.ctx4d"], name=f"{pn}attn.ctx"))
            if "attn.scale" not in init_names:
                inits.append(numpy_helper.from_array(
                    np.array([1.0 / np.sqrt(head_dim)], dtype=np.float32), "attn.scale"))
                init_names.add("attn.scale")
            ctx_shape = f"{pn}attn.ctx_shape"
            if ctx_shape not in init_names:
                inits.append(numpy_helper.from_array(
                    np.array([1, sequence, q_heads * head_dim], dtype=np.int64), ctx_shape))
                init_names.add(ctx_shape)
            # [N, S, H] -> [S, N, H] before flattening: a direct reshape would reorder the
            # sequence and head axes, which is exactly the kind of silent corruption a
            # numeric check exists to catch.
            add(helper.make_node("Transpose", [f"{pn}attn.ctx4d"], [f"{pn}attn.ctxTS"],
                                 name=f"{pn}attn.ctx_transpose", perm=[0, 2, 1, 3]))
            add(helper.make_node("Reshape", [f"{pn}attn.ctxTS", ctx_shape],
                                 [f"{pn}attn.context"], name=f"{pn}attn.ctx_reshape"))
        else:
            add(helper.make_node(
            "GroupQueryAttention",
            [f"{pn}attn.q_proj", f"{pn}attn.k_proj", f"{pn}attn.v_proj",
             f"{pn}attn.past_key", f"{pn}attn.past_value", f"{pn}attn.seqlens_k",
             f"{pn}attn.total_sequence_length"],
            [f"{pn}attn.context", f"{pn}attn.present_key", f"{pn}attn.present_value"],
            name=f"{pn}attn.gqa", domain="com.microsoft",
            num_heads=q_heads, kv_num_heads=kv_heads,
            # No rotary in the fixture: with rotary the head layout interacts with position
            # encoding, which would make a head-range shard incomparable to the whole model.
            do_rotary=0))
        node, w = matmul_nbits(f"{pn}attn.o_proj", f"{pn}attn.context", hidden,
                               q_width, rng, f"{p}attn.o_proj.MatMul.weight")
        add(node, w)
        add(helper.make_node("Add", [x, f"{pn}attn.o_proj"], [f"{pn}attn.residual"],
                             name=f"{pn}attn.residual_add"))
        # MLP block starts at the post-attention normalization.
        add(helper.make_node("Cast", [f"{pn}attn.residual"],
                             [f"{pn}post_attention_layernorm.cast"],
                             name=f"{pn}post_attention_layernorm", to=TensorProto.FLOAT))
        node, w = matmul_nbits(f"{pn}mlp.gate_proj", f"{pn}post_attention_layernorm.cast",
                               ffn, hidden, rng, f"{p}mlp.gate_proj.MatMul.weight")
        add(node, w)
        node, w = matmul_nbits(f"{pn}mlp.up_proj", f"{pn}post_attention_layernorm.cast",
                               ffn, hidden, rng, f"{p}mlp.up_proj.MatMul.weight")
        add(node, w)
        add(helper.make_node("Mul", [f"{pn}mlp.gate_proj", f"{pn}mlp.up_proj"],
                             [f"{pn}mlp.act"], name=f"{pn}mlp.act"))
        node, w = matmul_nbits(f"{pn}mlp.down_proj", f"{pn}mlp.act", hidden, ffn, rng,
                               f"{p}mlp.down_proj.MatMul.weight")
        add(node, w)
        add(helper.make_node("Add", [f"{pn}attn.residual", f"{pn}mlp.down_proj"],
                             [f"{pn}mlp.out"], name=f"{pn}mlp.out_add"))
        if layer + 1 < layers:
            add(helper.make_node("Identity", [f"{pn}mlp.out"],
                                 [f"model.layers.{layer + 1}/input"],
                                 name=f"{pn}next"))

    # HEAD: final norm at layers.<layers> and the tied lm_head.
    add(helper.make_node("Cast", [f"model.layers.{layers - 1}/mlp.out"],
                         [f"model.layers.{layers}/norm"],
                         name=f"model.layers.{layers}/norm", to=TensorProto.FLOAT))
    add(helper.make_node("MatMul", [f"model.layers.{layers}/norm", "lm_head.weight"],
                         ["logits"], name="lm_head"),
        [numpy_helper.from_array(rng.standard_normal((hidden, vocab)).astype(np.float32),
                                 "lm_head.weight")])

    graph = helper.make_graph(
        nodes, "spec242-four-layer-qwen",
        [helper.make_tensor_value_info("input_ids", TensorProto.INT64, [1, sequence])],
        [helper.make_tensor_value_info("logits", TensorProto.FLOAT, [1, sequence, vocab])],
        initializer=inits)
    model = helper.make_model(graph, opset_imports=[helper.make_opsetid("", 17),
                                                    helper.make_opsetid("com.microsoft", 1)])
    model.ir_version = 8
    # The assembler reads a boundary tensor's declared type from the source, so the
    # intermediate value_info must be present rather than implied.
    model = onnx.shape_inference.infer_shapes(model)
    onnx.checker.check_model(model)
    onnx.save(model, path)
    data = open(path, "rb").read()
    print(f"{path} nodes={len(nodes)} initializers={len(inits)} "
          f"sha256={hashlib.sha256(data).hexdigest()}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--out", default="tests/fixtures/spec242/four-layer-qwen.onnx")
    parser.add_argument("--attention", default="gqa", choices=["gqa", "matmul"],
                        help="gqa for shape derivation, matmul for numeric slicing checks")
    args = parser.parse_args()
    build(args.out, attention=args.attention)
